export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

const COMPONENT_TYPES = ["rune", "moonstone"];
const COMPONENT_BASE_PREMIUM = 25;
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

function isComponent(item: Item): boolean {
  return COMPONENT_TYPES.includes(item.type);
}

function countByType(items: Item[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
}

function alikeComponentsBasePremium(count: number): number {
  return count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * COMPONENT_BASE_PREMIUM;
}

function componentsBasePremiumOf(components: Item[]): number {
  let total = 0;
  for (const count of countByType(components).values()) {
    total += alikeComponentsBasePremium(count);
  }
  return total;
}

function mainItemsBasePremiumOf(mainItems: Item[]): number {
  return mainItems.reduce((total, item) => total + MAIN_ITEM_BASE_PREMIUMS[item.type], 0);
}

function policyBasePremiumOf(items: Item[]): number {
  return (
    mainItemsBasePremiumOf(items.filter((item) => !isComponent(item))) +
    componentsBasePremiumOf(items.filter(isComponent))
  );
}

export function quote(customer: Customer, items: Item[]): number {
  const policyBasePremium = policyBasePremiumOf(items);
  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  return policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE;
}

import { describe, expect, it } from "vitest";

import { quote } from "./quote.js";

describe("MHPCO Claim Office", () => {
  // --- Quote: processing fee and empty policy ---
  it("quotes an empty item list -- premium 5 G (processing fee only)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [])).toBe(5);
  });

  // --- Quote: base premiums per main item type ---
  it("quotes a single plain sword -- base 100 G + 10 G first insurance + 5 G fee = 115 G", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword" }])).toBe(115);
  });
  it("quotes a single plain amulet -- base 60 G + 6 G first insurance + 5 G fee = 71 G", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "amulet" }])).toBe(71);
  });
  it("quotes a single plain staff -- base 80 G + 8 G first insurance + 5 G fee = 93 G", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "staff" }])).toBe(93);
  });
  it("quotes a single plain potion -- base 40 G + 4 G first insurance + 5 G fee = 49 G", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "potion" }])).toBe(49);
  });

  // --- Quote: component base premiums and the building block of 3 alike ---
  it("quotes a single rune -- base 25 G component premium", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "rune" }])).toBe(25 + 2.5 + 5);
  });
  it("quotes a single moonstone -- base 25 G component premium", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "moonstone" }])).toBe(25 + 2.5 + 5);
  });
  it("quotes 2 runes -- base premium 50 G (no block)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "rune" }, { type: "rune" }])).toBe(50 + 5 + 5);
  });
  it("quotes 3 runes -- base premium 60 G (block applies)", () => {
    const threeRunes = [{ type: "rune" }, { type: "rune" }, { type: "rune" }];
    expect(quote({ yearsWithMHPCO: 0 }, threeRunes)).toBe(60 + 6 + 5);
  });
  it.todo("quotes 4 runes -- base premium 100 G (no block; block requires exactly 3)");
  it.todo("quotes 7 runes -- base premium 175 G (no block at 7)");
  it.todo("quotes 2 runes + 1 moonstone -- base premium 75 G (no block: different types)");
  it.todo("quotes 3 runes + 3 moonstones -- base premium 120 G (two separate blocks)");

  // --- Quote: item-specific modifiers ---
  it.todo("applies the 50% curse surcharge to the cursed item's base premium -- cursed sword base 100 G -> 150 G");
  it.todo("applies the 30% high-enchantment surcharge at enchantment exactly 5 -- sword base 100 G -> 130 G");
  it.todo("applies no high-enchantment surcharge at enchantment 4 -- sword base premium stays 100 G");
  it.todo("applies both curse and high-enchantment surcharges to a cursed sword with enchantment exactly 5 -- 100 + 50 + 30 = 180 G");

  // --- Quote: modifier scope on multi-item policies ---
  it.todo("applies the curse surcharge only to the cursed item on a multi-item policy -- cursed sword + plain amulet: base 160 G + 50 G curse = 210 G before further modifiers and fee");

  // --- Quote: policy-wide modifiers ---
  it.todo("applies the 20% loyalty discount at exactly 2 years with MHPCO -- policy base 100 G -> -20 G");
  it.todo("applies no loyalty discount at 1 year with MHPCO");
  it.todo("applies the 10% first-insurance surcharge to the policy base premium");
  it.todo("applies the 15% follow-up discount on each contract after the customer's first quote");
  it.todo("applies no follow-up discount on the customer's first quote");
  it.todo("applies the first-insurance surcharge on a follow-up contract too -- each quoted item is a first insurance regardless of customer history");

  // --- Quote: rounding in the MHPCO's favour ---
  it.todo("rounds a premium of 197.5 G up to 198 G (MHPCO's favour)");
  it.todo("keeps intermediate premium amounts as fractions and rounds only the final premium");

  // --- Quote: integration examples ---
  it.todo("quotes newcomer with a cursed steel sword (enchantment 3), 0 years -- premium 165 G");
  it.todo("quotes long-standing customer's second contract, cursed steel sword (enchantment 7), 3 years -- premium 160 G");

  // --- Quote: error cases ---
  it.todo("rejects a quote containing an unknown item type (e.g. broomstick) -- CLI exits non-zero, error on stderr, no results on stdout");

  // --- Claim: insurance sum and cap ---
  it.todo("caps a single-sword policy at 2000 G -- insurance sum 1000 G, cap = 2 x sum");
  it.todo("computes the insurance sum of a sword + amulet policy as 1600 G -- cap 3200 G");
  it.todo("computes the insurance sum of two swords as 2000 G -- cap 4000 G");
  it.todo("computes the insurance sum of a sword + 3 runes as 1750 G -- the block discount affects the premium only, cap 3500 G");
  it.todo("bases the cap on the unmodified insurance value -- cursed sword (premium 165 G) still has cap 2000 G");

  // --- Claim: standard reimbursement and deductible ---
  it.todo("pays 400 G for a regular steel sword (enchantment 3) with damage 500 G -- full reimbursement minus 100 G deductible");
  it.todo("pays 100 G for a damaged rune (no enchantment, no material) with damage 200 G -- 200 - 100 deductible");
  it.todo("applies the 100 G deductible once per damaged item -- sword 500 G + amulet 300 G in one incident = payout 600 G");

  // --- Claim: special clauses ---
  it.todo("reimburses 50% for damage to an item with enchantment exactly 8 -- dragon sword, damage 1000 G -> payout 400 G");
  it.todo("fully reimburses damage to a dragon-material item -- dragon sword enchantment 5, damage 800 G -> payout 700 G");
  it.todo("prefers the 50% high-enchantment rule over full dragon reimbursement -- dragon sword enchantment 9, damage 1000 G -> payout 400 G");
  it.todo("applies only the high-enchantment clause to a steel sword enchantment 9, damage 1000 G -> payout 400 G");

  // --- Claim: cap exhaustion across successive claims ---
  it.todo("pays 1400 G and leaves cap remaining 600 G for the first 1500 G claim on a sword policy (cap 2000 G)");
  it.todo("reduces the second 1500 G claim to the remaining cap -- payout 600 G, cap remaining 0 G");

  // --- Claim: multiple items of the same type ---
  it.todo("treats each damage entry of a repeated item type as a separate damage with its own deductible -- two swords, two sword damages");
  it.todo("rejects a claim with more damage entries of a type than the policy covers -- CLI exits non-zero with an error on stderr");

  // --- Claim: rounding in the MHPCO's favour ---
  it.todo("rounds a payout of 350.5 G down to 350 G (MHPCO's favour)");

  // --- Claim: error cases ---
  it.todo("rejects a claim referencing an item not covered by the policy (amulet damaged, only a sword insured) -- CLI exits non-zero with an error on stderr");
  it.todo("rejects a claim referencing an unknown item type -- CLI exits non-zero with an error on stderr");
  it.todo("rejects a claim with a negative damage amount (-200) -- CLI exits non-zero with an error on stderr");

  // --- CLI: end-to-end scenario wiring ---
  it.todo("reads a scenario from stdin and writes {results: [...]} to stdout in step order");
  it.todo("resolves a claim step's policy field as the zero-based index of the quote step that created the policy");
  it.todo("runs the schema example end to end -- amulet quote then 200 G amulet claim -> premium and payout/remainingCap");
});

